    const tombstones: MemoryTombstone[] = [
      { target: { kind: "node", id: "mem:erased" }, principal_owner: OWNER },
    ];
    const out = recallMemory(doc, ctx, { asOf: T }, tombstones);
    expect(out.notes.map((n) => n.id)).toEqual(["mem:keep"]);
